def candidate_line(raw: str, *, expected_issue: str = "") -> str:
    """The rendered line the host would build from this proposal, before its checks."""

    try:
        proposal = json.loads(raw)
    except Exception:
        return ""
    if not isinstance(proposal, dict):
        return ""
    cause, fix = proposal.get("cause"), proposal.get("fix")
    if not all(isinstance(value, str) for value in (cause, fix)):
        return ""
    issue = proposal.get("issue", expected_issue)
    return f"RESULT issue={issue} cause={cause} fix={fix}"


def declared_facts(raw: str) -> list[str]:
    """The strings the proposal declared, or an empty list when it is unreadable."""

    try:
        proposal = json.loads(raw)
    except Exception:
        return []
    if not isinstance(proposal, dict):
        return []
    facts = proposal.get("facts")
    return [str(fact) for fact in facts] if isinstance(facts, list) else []


